// ──────────────────────────── tests ──────────────────────────────────────

static List<Row> Rows(int count) =>
    Enumerable.Range(1, count).Select(n => new Row(n, "r" + n, true)).ToList();

Test("page 1 is the first n rows", () =>
    Eq(Page(Rows(25), 1, 10).Select(r => r.Id), Enumerable.Range(1, 10)));

Test("page 2 continues where page 1 stopped", () =>
    Eq(Page(Rows(25), 2, 10).Select(r => r.Id), Enumerable.Range(11, 10)));

Test("the last page is short, not padded", () =>
    Eq(Page(Rows(25), 3, 10).Count, 5));

Test("a page past the end is empty, not an error", () =>
    Eq(Page(Rows(25), 99, 10), Array.Empty<Row>()));

Test("paging is stable even when the source is shuffled", () =>
{
    // Same rows, different input order. If the implementation forgot to
    // order, these two disagree.
    var rows = Rows(25);
    var shuffled = rows.OrderByDescending(r => r.Id % 7).ThenByDescending(r => r.Id).ToList();

    Eq(Page(shuffled, 2, 10).Select(r => r.Id), Page(rows, 2, 10).Select(r => r.Id));
});

Test("every row appears on exactly one page", () =>
{
    var pages = AllPages(Rows(25), 10);

    Eq(pages.Count, 3);
    Eq(pages.Select(p => p.Count), new[] { 10, 10, 5 });
    Eq(pages.SelectMany(p => p).Select(r => r.Id), Enumerable.Range(1, 25));
});

Test("chunking an empty list gives no pages at all", () =>
    Eq(AllPages([], 10).Count, 0));

Test("TakeWhile stops at the first failure and does not resume", () =>
{
    // Note the difference from Where: row 4 is fine, and it is still
    // excluded, because the sequence STOPPED at row 3.
    var rows = new List<Row>
    {
        new(1, "a", true), new(2, "b", true), new(3, "c", false), new(4, "d", true),
    };

    Eq(UntilFirstFailure(rows).Select(r => r.Id), new[] { 1, 2 });
});

Test("SkipWhile is the mirror image", () =>
{
    var rows = new List<Row>
    {
        new(1, "a", true), new(2, "b", true), new(3, "c", false), new(4, "d", true),
    };

    Eq(FromFirstFailure(rows).Select(r => r.Id), new[] { 3, 4 });
});

Test("all-good and all-bad are the degenerate cases", () =>
{
    Eq(UntilFirstFailure(Rows(3)).Count, 3);
    Eq(FromFirstFailure(Rows(3)).Count, 0);
});

// ──────────────────────────── tests ──────────────────────────────────────

Test("Summarise gets the right answer", () =>
    Eq(Summarise([1, 2, 3, 4]), (4, 10)));

Test("...touching the source only once", () =>
{
    // `numbers.Count()` then `numbers.Sum()` is two passes. Against a
    // database that is two queries for one screen.
    var counter = new Counter();
    Summarise(counter.Watch([1, 2, 3, 4]));

    Eq(counter.Passes, 1, "the source was enumerated " + counter.Passes + " times");
});

Test("Summarise handles an empty source", () =>
    Eq(Summarise([]), (0, 0)));

Test("DoubleAndRecord doubles", () =>
    Eq(DoubleAndRecord([1, 2, 3], []), new[] { 2, 4, 6 }));

Test("the recording happens once per item, without the caller enumerating", () =>
{
    // A lazy `Select` with a side effect records nothing until someone
    // iterates, and records twice if two people do.
    var seen = new List<int>();
    DoubleAndRecord([1, 2, 3], seen);

    Eq(seen, new[] { 1, 2, 3 });
});

Test("...and does not record twice when the result is read twice", () =>
{
    var seen = new List<int>();
    var doubled = DoubleAndRecord([1, 2, 3], seen);

    _ = doubled.Count;
    _ = doubled.Sum();

    Eq(seen, new[] { 1, 2, 3 });
});

Test("TheUserWith finds the one", () =>
    Eq(TheUserWith([new(1, "ada@x.com"), new(2, "bob@x.com")], "bob@x.com").Id, 2));

Test("a duplicate is an error, not a coin toss", () =>
{
    // This is the whole argument for Single. With First, the duplicate rows
    // sit in the database for a year and one of them silently wins.
    var users = new List<User> { new(1, "ada@x.com"), new(2, "ada@x.com") };

    Throws<InvalidOperationException>(() => TheUserWith(users, "ada@x.com"));
});

Test("no match is also an error here", () =>
    Throws<InvalidOperationException>(() => TheUserWith([], "nobody@x.com")));

Test("a real zero is distinguishable from no result", () =>
{
    Eq(FirstIdOrNull([0, 1, 2]), 0);
    Eq(FirstIdOrNull([]), null);
    Ok(FirstIdOrNull([]) != FirstIdOrNull([0]), "0 and 'nothing' must differ");
});

